import React, { useState, useRef, useEffect } from 'react';
import { Bell, Check, Trash2, X } from 'lucide-react';
import { useNotifications } from '../context/NotificationContext';
import { motion, AnimatePresence } from 'framer-motion';

const NotificationBell = () => {
    const { notifications, unreadCount, markAllAsRead, clearAll, markAsRead } = useNotifications();
    const [isOpen, setIsOpen] = useState(false);
    const dropdownRef = useRef(null);

    // Close on click outside
    useEffect(() => {
        const handleClickOutside = (event) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // Tone Colors
    const getToneStyles = (tone) => {
        switch (tone) {
            case 'Professional': return 'bg-gray-50 border-gray-100';
            case 'Friendly': return 'bg-blue-50 border-blue-100';
            case 'Comedy': return 'bg-yellow-50 border-yellow-100';
            case 'Flirty': return 'bg-pink-50 border-pink-100';
            default: return 'bg-white border-gray-100';
        }
    };

    return (
        <div className="relative" ref={dropdownRef}>
            {/* Bell Button */}
            <button
                onClick={() => setIsOpen(!isOpen)}
                className="relative p-2 rounded-xl text-gray-500 hover:text-orange-600 hover:bg-orange-50 transition-all group"
            >
                <Bell className={`w-6 h-6 transition-transform ${isOpen ? 'rotate-12 text-orange-600' : ''}`} />
                {unreadCount > 0 && (
                    <span className="absolute top-1 right-1 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-white animate-pulse"></span>
                )}
            </button>

            {/* Dropdown */}
            <AnimatePresence>
                {isOpen && (
                    <motion.div
                        initial={{ opacity: 0, y: 10, scale: 0.95 }}
                        animate={{ opacity: 1, y: 0, scale: 1 }}
                        exit={{ opacity: 0, y: 10, scale: 0.95 }}
                        transition={{ duration: 0.2 }}
                        className="absolute right-0 mt-3 w-80 sm:w-96 bg-white/90 backdrop-blur-xl border border-white/50 shadow-2xl rounded-3xl overflow-hidden z-50 origin-top-right ring-1 ring-black/5"
                    >
                        {/* Header */}
                        <div className="px-5 py-4 border-b border-gray-100 flex items-center justify-between bg-white/50">
                            <h3 className="font-bold text-gray-900">Notifications</h3>
                            <div className="flex items-center gap-2">
                                {unreadCount > 0 && (
                                    <button onClick={markAllAsRead} className="p-1.5 text-xs font-bold text-orange-600 bg-orange-50 rounded-lg hover:bg-orange-100 transition-colors" title="Mark all read">
                                        <Check size={14} />
                                    </button>
                                )}
                                <button onClick={clearAll} className="p-1.5 text-xs font-bold text-gray-400 hover:text-red-500 transition-colors" title="Clear all">
                                    <Trash2 size={14} />
                                </button>
                                <button onClick={() => setIsOpen(false)} className="md:hidden p-1.5 text-gray-400">
                                    <X size={14} />
                                </button>
                            </div>
                        </div>

                        {/* List */}
                        <div className="max-h-[60vh] overflow-y-auto p-2 space-y-2 no-scrollbar">
                            {notifications.length > 0 ? (
                                notifications.map((notif) => (
                                    <div
                                        key={notif.id}
                                        onClick={() => markAsRead(notif.id)}
                                        className={`p-4 rounded-2xl border transition-all cursor-pointer relative group ${getToneStyles(notif.tone)} ${notif.read ? 'opacity-60 grayscale-[0.5]' : 'opacity-100 shadow-sm'}`}
                                    >
                                        <div className="flex gap-3">
                                            {/* Icon based on Tone/Type could go here */}
                                            <div className="flex-1">
                                                <p className="text-sm font-bold text-gray-900 leading-snug mb-1">{notif.message}</p>
                                                <div className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-wider text-gray-400">
                                                    <span>{notif.tone}</span> ΓÇó <span>{new Date(notif.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                                                </div>
                                            </div>
                                            {!notif.read && (
                                                <div className="w-2 h-2 bg-orange-500 rounded-full mt-1.5 shrink-0" />
                                            )}
                                        </div>
                                    </div>
                                ))
                            ) : (
                                <div className="py-12 text-center text-gray-400">
                                    <Bell className="w-8 h-8 mx-auto mb-2 opacity-20" />
                                    <p className="text-xs font-bold uppercase tracking-widest">No Updates</p>
                                </div>
                            )}
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
};

export default NotificationBell;

import React from 'react';
import { useNotifications } from '../context/NotificationContext';
import Button from './Button';
import { Bell, Smile, Zap, Heart, Briefcase, Lock, Check } from 'lucide-react';
import { motion } from 'framer-motion';

const NotificationPreferences = () => {
    const { preferences, updatePreferences, requestPermission, permissionStatus, sendTestNotification, triggerMarketing, triggerAbandonedCart } = useNotifications();

    const tones = [
        { id: 'Professional', icon: Briefcase, color: 'bg-gray-100 text-gray-600', desc: 'Concise & Helpful' },
        { id: 'Friendly', icon: Smile, color: 'bg-blue-100 text-blue-600', desc: 'Warm & Inviting' },
        { id: 'Comedy', icon: Zap, color: 'bg-yellow-100 text-yellow-600', desc: 'Witty & Fun' },
        { id: 'Flirty', icon: Heart, color: 'bg-pink-100 text-pink-600', desc: 'Playful & Charming' },
    ];

    return (
        <div className="frosted-paper p-8 rounded-3xl border border-white/60">
            <div className="flex items-center justify-between mb-6">
                <h2 className="text-xl font-black text-gray-900 flex items-center gap-2">
                    <Bell size={24} /> Notification Style
                </h2>
            </div>

            {/* Granular Toggles */}
            <div className="mb-6 grid grid-cols-2 gap-3">
                {[
                    { key: 'orderUpdates', label: 'Orders' },
                    { key: 'marketing', label: 'Marketing' },
                    { key: 'loyalty', label: 'Loyalty' },
                    { key: 'cartReminders', label: 'Cart' }
                ].map(({ key, label }) => (
                    <div key={key} className="flex items-center justify-between p-3 bg-white rounded-xl border border-gray-100">
                        <span className="text-sm font-bold text-gray-700 capitalize">{label}</span>
                        <button
                            onClick={() => {
                                updatePreferences({ [key]: !preferences[key] });
                            }}
                            className={`w-8 h-5 rounded-full transition-colors flex items-center px-0.5 ${(preferences[key] ?? true) ? 'bg-orange-500' : 'bg-gray-200'
                                }`}
                        >
                            <div className={`w-4 h-4 bg-white rounded-full shadow-sm transform transition-transform ${(preferences[key] ?? true) ? 'translate-x-3' : 'translate-x-0'
                                }`} />
                        </button>
                    </div>
                ))}
            </div>

            {/* Push Permission Status */}
            <div className="mb-8 bg-gray-50/50 p-4 rounded-2xl border border-gray-100 flex items-center justify-between">
                <div>
                    <h3 className="text-sm font-bold text-gray-900">Device Permissions</h3>
                    <p className="text-xs text-gray-500">
                        {permissionStatus === 'granted'
                            ? "You're all set to receive updates on this device."
                            : "Enable push notifications to get real-time order updates."}
                    </p>
                </div>
                {permissionStatus === 'granted' ? (
                    <div className="flex items-center gap-2">
                        <div className="flex items-center gap-2 text-green-600 bg-green-50 px-3 py-1.5 rounded-lg border border-green-100">
                            <Check size={14} strokeWidth={3} />
                            <span className="text-xs font-black uppercase tracking-wide">Active</span>
                        </div>
                        <Button
                            onClick={sendTestNotification}
                            size="sm"
                            variant="secondary"
                            className="text-xs h-8"
                        >
                            Test Push
                        </Button>
                        <Button
                            onClick={triggerMarketing}
                            size="sm"
                            variant="outline"
                            className="text-xs h-8 ml-2"
                        >
                            Trigger Marketing
                        </Button>
                        <Button
                            onClick={triggerAbandonedCart}
                            size="sm"
                            variant="outline"
                            className="text-xs h-8 ml-2 text-red-500 border-red-200 bg-red-50"
                        >
                            Trigger AC
                        </Button>
                    </div>
                ) : (
                    <Button
                        onClick={requestPermission}
                        size="sm"
                        variant="primary"
                        className="shadow-lg shadow-orange-500/20"
                    >
                        Enable Push
                    </Button>
                )}
            </div>

            <div className="grid grid-cols-2 gap-4">
                {tones.map((tone) => (
                    <button
                        key={tone.id}
                        onClick={() => updatePreferences({ tone: tone.id })}
                        className={`relative p-4 rounded-2xl border transition-all text-left group ${preferences.tone === tone.id ? 'border-orange-500 bg-orange-50' : 'border-gray-200 hover:border-orange-200 bg-white'
                            }`}
                    >
                        <div className={`w-10 h-10 rounded-xl flex items-center justify-center mb-3 ${tone.color}`}>
                            <tone.icon size={20} />
                        </div>
                        <h3 className="font-bold text-gray-900 text-sm mb-1">{tone.id}</h3>
                        <p className="text-xs text-gray-500 font-medium">{tone.desc}</p>

                        {preferences.tone === tone.id && (
                            <motion.div layoutId="active-ring" className="absolute inset-0 border-2 border-orange-500 rounded-2xl" />
                        )}
                    </button>
                ))}
            </div>

            <p className="mt-6 text-xs font-medium text-gray-400 text-center">
                We'll use AI to customize your updates based on this style.
            </p>
        </div>
    );
};

export default NotificationPreferences;

import React from 'react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import Card from '../common/Card';
import { Filter } from 'lucide-react';

const ConversionFunnel = ({ stats }) => {
    // Mock Funnel Data based on Order Statuses
    // In a real app, this would be: View Content -> Add to Cart -> Initiate Checkout -> Purchase
    // Here we visualize: Placed -> Processing -> Delivered

    // We don't have historical "Placed" count easily without querying all, so we'll approximate 
    // or just show the distribution of current order statuses as a "Health Funnel".

    const data = [
        { name: 'Total Orders', value: stats?.totalOrders || 0, fill: '#c2410c' }, // Orange-800
        { name: 'Processing', value: (stats?.totalOrders || 0) - (stats?.pendingOrders || 0), fill: '#ea580c' }, // Orange-600
        { name: 'Delivered', value: stats?.deliveredOrders || 0, fill: '#f97316' }, // Orange-500
    ];

    return (
        <Card className="h-full min-h-[300px] flex flex-col">
            <div className="mb-6">
                <h3 className="font-black text-gray-900 flex items-center gap-2">
                    <Filter size={20} className="text-orange-500" />
                    Order Fulfillment Funnel
                </h3>
                <p className="text-xs font-bold text-gray-400 uppercase tracking-widest">Efficiency Metrics</p>
            </div>

            <div className="flex-1 w-full min-h-[200px] flex flex-col justify-center space-y-4">
                {data.map((item, index) => {
                    // Caclulate strict percentage based on previous step to look like a funnel
                    // But here, let's just use percentage of Total
                    const max = data[0].value || 1;
                    const percent = Math.round((item.value / max) * 100);

                    return (
                        <div key={item.name} className="relative">
                            <div className="flex justify-between text-sm font-bold text-gray-700 mb-1 z-10 relative">
                                <span>{item.name}</span>
                                <span>{item.value} ({percent}%)</span>
                            </div>
                            <div className="h-3 w-full bg-gray-100 rounded-full overflow-hidden">
                                <div
                                    className="h-full rounded-full transition-all duration-1000 ease-out"
                                    style={{
                                        width: `${percent}%`,
                                        backgroundColor: item.fill
                                    }}
                                ></div>
                            </div>
                        </div>
                    );
                })}
            </div>

            <div className="mt-4 p-4 bg-gray-50 rounded-xl">
                <p className="text-xs text-gray-500 text-center leading-relaxed">
                    <strong>Insight:</strong> {(data[2].value / (data[0].value || 1) * 100).toFixed(1)}% of all orders have been successfully delivered.
                </p>
            </div>
        </Card>
    );
};

export default ConversionFunnel;

