import React, { createContext, useContext, useState, useEffect } from 'react';
import { useAuth } from './AuthContext';
import { usePerformance } from '../hooks/usePerformance';
import { generateNotificationCopy } from '../services/aiService';
import { CartContext } from './CartContext';
import { WishlistContext } from './WishlistContext';
import { useEngagement } from '../hooks/useEngagement';
import { doc, onSnapshot, updateDoc, setDoc, arrayUnion } from 'firebase/firestore';
import { db, messaging, functions } from '../firebase/firebase';
import { onMessage } from 'firebase/messaging';
import { httpsCallable } from 'firebase/functions';
import { showBrowserNotification } from '../utils/showNotification';
import { requestFcmToken } from '../firebase/messaging';
import { collection, query, where, orderBy, limit, addDoc, getDocs, writeBatch } from 'firebase/firestore';

const NotificationContext = createContext();

export const useNotifications = () => useContext(NotificationContext);

export const NotificationProvider = ({ children }) => {
    const { currentUser } = useAuth();
    const { isLowPowerMode } = usePerformance();
    const { logEvent } = useEngagement();

    // Default States
    const defaultPreferences = {
        userId: currentUser?.uid,
        orderUpdates: true,
        marketing: true,
        loyalty: true,
        cartReminders: true
    };
    const [preferences, setPreferences] = useState(defaultPreferences);
    const [notifications, setNotifications] = useState([]);
    const [fcmToken, setFcmToken] = useState(null);
    const [permissionStatus, setPermissionStatus] = useState(Notification.permission);

    // Daily Limit Tracker ({ date: 'YYYY-MM-DD', count: 0 })
    const [dailyCount, setDailyCount] = useState(() => {
        const saved = localStorage.getItem('sharma-notification-daily-count');
        return saved ? JSON.parse(saved) : { date: new Date().toDateString(), count: 0 };
    });

    // --- PERSISTENCE LOGIC ---
    useEffect(() => {
        if (!currentUser) {
            // GUEST MODE: Load from LocalStorage
            const savedPrefs = localStorage.getItem('sharma-notification-prefs');
            const savedNotifs = localStorage.getItem('sharma-notifications');
            if (savedPrefs) setPreferences(JSON.parse(savedPrefs));
            if (savedNotifs) setNotifications(JSON.parse(savedNotifs));
            return;
        }

        // USER MODE: Sync with Firestore
        // 1. Listen to User Preferences
        const prefsRef = doc(db, 'notificationPreferences', currentUser.uid);
        const prefsUnsubscribe = onSnapshot(prefsRef, (docSnap) => {
            if (docSnap.exists()) {
                setPreferences(prev => ({ ...prev, ...docSnap.data() }));
            } else {
                // Initialize defaults if missing
                setDoc(prefsRef, defaultPreferences, { merge: true });
            }
        }, (error) => {
            if (error.code === 'permission-denied') {
                console.warn("Notification prefs access denied. Using defaults.");
            } else {
                console.error("Error fetching notification prefs:", error);
            }
        });

        // 2. Listen to User Notifications from 'notifications' collection
        const notifQuery = query(
            collection(db, 'notifications'),
            where('userId', '==', currentUser.uid),
            orderBy('timestamp', 'desc'),
            limit(50)
        );

        const notifUnsubscribe = onSnapshot(notifQuery, (snapshot) => {
            const fetchedNotifs = snapshot.docs.map(doc => ({
                id: doc.id,
                ...doc.data()
            }));
            setNotifications(fetchedNotifs);
        }, (error) => {
            if (error.code === 'permission-denied') {
                console.warn("Notifications access denied. Using empty list.");
                setNotifications([]);
            } else {
                console.error("Error fetching notifications:", error);
            }
        });

        return () => {
            prefsUnsubscribe();
            notifUnsubscribe();
        };
    }, [currentUser]);

    // Save to LocalStorage (Guest) or Firestore (User)
    useEffect(() => {
        if (!currentUser) {
            localStorage.setItem('sharma-notification-prefs', JSON.stringify(preferences));
            localStorage.setItem('sharma-notifications', JSON.stringify(notifications));
        }
        // Firestore updates happen via the action functions to allow atomicity
    }, [preferences, notifications, currentUser]);

    // Check Daily Limit
    useEffect(() => {
        localStorage.setItem('sharma-notification-daily-count', JSON.stringify(dailyCount));
    }, [dailyCount]);

    const checkDailyUsage = () => {
        const today = new Date().toDateString();
        if (dailyCount.date !== today) {
            setDailyCount({ date: today, count: 0 });
            return true;
        }
        return dailyCount.count < 5;
    };

    // Smart Triggers (Cart / Wishlist)
    const { cartCount, cartTotal } = useContext(CartContext);
    const { wishlistCount } = useContext(WishlistContext);

    useEffect(() => {
        if (cartCount > 0) {
            const timer = setTimeout(() => {
                addNotification('engagement', `You have ${cartCount} items (Γé╣${cartTotal}) waiting in your cart.`);
            }, 10000);
            return () => clearTimeout(timer);
        }
    }, [cartCount]);

    useEffect(() => {
        if (wishlistCount > 0) {
            const timer = setTimeout(() => {
                addNotification('engagement', `Your wishlist has ${wishlistCount} items. Don't let them go out of stock!`);
            }, 15000);
            return () => clearTimeout(timer);
        }
    }, [wishlistCount]);

    const addNotification = async (type, rawMessage, force = false) => {
        // Flat Preference Check
        // Type map: 'order' -> orderUpdates, 'marketing' -> marketing, 'loyalty' -> loyalty, 'cart' -> cartReminders
        const typeMap = {
            'order': 'orderUpdates',
            'marketing': 'marketing',
            'loyalty': 'loyalty',
            'cart': 'cartReminders'
        };

        const prefKey = typeMap[type];
        if (prefKey && preferences[prefKey] === false && !force) {
            return;
        }

        if (isLowPowerMode && type !== 'order') return;

        let finalMessage = rawMessage;
        let toneUsed = 'Neutral';

        // AI Styling
        if (type === 'engagement' && checkDailyUsage()) {
            toneUsed = preferences.tone;
            try {
                // Optimization: Skip AI call if tone is Neutral or Simple
                if (toneUsed !== 'Neutral') {
                    const aiMessage = await generateNotificationCopy(rawMessage, toneUsed);
                    if (aiMessage) finalMessage = aiMessage;
                }
                setDailyCount(prev => ({ ...prev, count: prev.count + 1 }));
            } catch (e) {
                console.error("Notification Gen Error", e);
            }
        }

        const newNotif = {
            id: Date.now().toString(),
            type,
            message: finalMessage,
            tone: toneUsed,
            read: false,
            createdAt: new Date().toISOString()
        };

        // Optimistic Update
        setNotifications(prev => [newNotif, ...prev].slice(0, 50));

        // Persist
        if (currentUser) {
            addDoc(collection(db, 'notifications'), {
                userId: currentUser.uid,
                type,
                title: 'Sharma Store',
                body: finalMessage,
                read: false,
                createdAt: new Date().toISOString(),
                tone: toneUsed,
                meta: {} // Optional meta field
            }).catch(e => console.error("Failed to add notification", e));
        }

        // Analytics & Sound
        logEvent('notification_sent', 'notification', { type, tone: toneUsed });
        if (preferences.sound && !isLowPowerMode) {
            // Play sound logic here
            // const audio = new Audio('/notification.mp3'); audio.play();
        }

        // TRIGGER BROWSER NOTIFICATION (Native)
        // Only if it's an engagement/order alert and permissions are granted
        // We skip this if it was a 'forced' foreground message to avoid double toast + system notif if desired,
        // but user requested "Notifications appear outside the tab".
        if (permissionStatus === 'granted' && preferences.enabled) {
            showBrowserNotification('Sharma Store', finalMessage);
        }
    };

    const markAsRead = async (id) => {
        // Optimistic
        const updatedNotifs = notifications.map(n => n.id === id ? { ...n, read: true } : n);
        setNotifications(updatedNotifs);

        if (currentUser) {
            const notifRef = doc(db, 'notifications', id);
            await updateDoc(notifRef, { read: true });
        }
    };

    const markAllAsRead = async () => {
        const updatedNotifs = notifications.map(n => ({ ...n, read: true }));
        setNotifications(updatedNotifs);

        if (currentUser) {
            const batch = writeBatch(db);
            notifications.forEach(n => {
                if (!n.read) {
                    const ref = doc(db, 'notifications', n.id);
                    batch.update(ref, { read: true });
                }
            });
            await batch.commit();
        }
    };

    const clearAll = async () => {
        setNotifications([]);
        if (currentUser) {
            // Deleting collection documents is expensive/complex client-side in bulk
            // For now, let's just mark deleted or actually delete batch.
            // A simple "clear" usually means "delete all".
            const batch = writeBatch(db);
            notifications.forEach(n => {
                const ref = doc(db, 'notifications', n.id);
                batch.delete(ref);
            });
            await batch.commit();
        }
    };

    const updatePreferences = async (newPrefs) => {
        const updated = { ...preferences, ...newPrefs };
        setPreferences(updated);

        if (currentUser) {
            const prefsRef = doc(db, 'notificationPreferences', currentUser.uid);
            await setDoc(prefsRef, updated, { merge: true });
        }
    };

    // --- FCM LOGIC ---
    const requestPermission = async () => {
        if (!currentUser) return; // Only save token if logged in (or handle guest tokens separately)

        const token = await requestFcmToken(currentUser.uid);
        setPermissionStatus(Notification.permission);
        if (token) {
            setFcmToken(token);
        }
        return token;
    };

    const triggerMarketing = async () => {
        if (!currentUser) return;
        try {
            const trigger = httpsCallable(functions, 'triggerDailyMarketing');
            await trigger();
            addNotification('announcement', 'Marketing campaign triggered!', true);
        } catch (error) {
            console.error(error);
            addNotification('alert', 'Failed to trigger campaign.', true);
        }
    };

    const triggerAbandonedCart = async () => {
        if (!currentUser) return;
        try {
            const trigger = httpsCallable(functions, 'triggerAbandonedCart');
            await trigger();
            // addNotification('announcement', 'Abandoned cart check triggered!', true); 
            // Don't show toast, let the real push come through if meaningful
        } catch (error) {
            console.error(error);
        }
    };

    const sendTestNotification = async () => {
        if (!currentUser) return;
        try {
            const sendTest = httpsCallable(functions, 'sendTestNotification');
            const result = await sendTest({ userId: currentUser.uid });
            addNotification('announcement', 'Test notification sent! Check your other tabs/devices.', true);
        } catch (error) {
            console.error("Failed to send test notification:", error);
            // Fallback to local
            showBrowserNotification('Sharma Store', 'Local Test: This is a fallback notification.');
            addNotification('alert', 'Cloud test failed. Sent local fallback.', true);
        }
    };

    // Listen for Foreground Messages (FCM)
    useEffect(() => {
        if (permissionStatus === 'granted') {
            const unsubscribe = onMessage(messaging, (payload) => {
                const title = payload.notification?.title || 'New Update';
                const body = payload.notification?.body || 'You have a new message.';

                // 1. Show In-App Toast
                addNotification(
                    'announcement',
                    body,
                    true // force
                );
            });
            return () => unsubscribe();
        }
    }, [permissionStatus]);

    const unreadCount = notifications.filter(n => !n.read).length;

    return (
        <NotificationContext.Provider value={{
            notifications,
            unreadCount,
            preferences,
            addNotification,
            markAsRead,
            markAllAsRead,
            clearAll,
            updatePreferences,
            requestPermission,
            permissionStatus,
            fcmToken,
            sendTestNotification,
            triggerMarketing,
            triggerAbandonedCart
        }}>
            {children}
        </NotificationContext.Provider>
    );
};

import React, { createContext, useContext, useState, useEffect, useMemo } from 'react';
import { collection, onSnapshot } from 'firebase/firestore';
import { db } from '../firebase/firebase';

const ShopContext = createContext();

export const ShopProvider = ({ children }) => {
    // 1. Source Data (Immutable) - "allProducts" as requested
    const [allProducts, setAllProducts] = useState([]);
    const [loading, setLoading] = useState(true);

    // 2. Filter State - "selectedCategory" as requested
    const [selectedCategory, setSelectedCategory] = useState("All");
    const [searchQuery, setSearchQuery] = useState('');
    const [sortBy, setSortBy] = useState("featured");

    // 3. Output State
    const [filteredProducts, setFilteredProducts] = useState([]);

    // 4. Fetch Data (Once per app load)
    useEffect(() => {
        const unsubscribe = onSnapshot(collection(db, "products"), (snapshot) => {
            const data = snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id }));
            // Set SOURCE of truth
            console.log("Fetched Products:", data);
            setAllProducts(data);
            setLoading(false);
        }, (error) => {
            if (error.code === 'permission-denied') {
                console.warn("Product access denied. Rules likely not deployed. Using empty list.");
                setAllProducts([]); // Handle gracefully
            } else {
                console.error("Error fetching products:", error);
            }
            setLoading(false);
        });
        return () => unsubscribe();
    }, []);

    // 5. Derived Filter Logic (Effect-based)
    useEffect(() => {

        let result = [...allProducts];

        // Search
        if (searchQuery) {
            const q = searchQuery.toLowerCase();
            result = result.filter(item =>
                item.name?.toLowerCase().includes(q) ||
                item.category?.toLowerCase().includes(q)
            );
        }

        // Category Filter (Case-Insensitive "all" check)
        // Treat "all", "All", "ALL" as the reset key
        if (selectedCategory && selectedCategory.toLowerCase() !== "all") {
            result = result.filter(p =>
                p.category?.toLowerCase() === selectedCategory.toLowerCase()
            );
        }

        // Sort
        if (sortBy === "price-low") {
            result.sort((a, b) => Number(a.price) - Number(b.price));
        } else if (sortBy === "price-high") {
            result.sort((a, b) => Number(b.price) - Number(a.price));
        }



        setFilteredProducts(result);
    }, [allProducts, selectedCategory, searchQuery, sortBy]);

    // 6. Derived Categories List
    const categories = useMemo(() => {
        const uniqueCats = Array.from(new Set(allProducts.map(p => p.category).filter(Boolean)));
        // Return "All" as layout friendly name, but logic handles it
        return ["All", ...uniqueCats.sort()];
    }, [allProducts]);

    // 7. Reset
    const resetFilters = () => {
        setSearchQuery("");
        setSelectedCategory("All");
        setSortBy("featured");
    };

    const value = {
        allProducts,
        filteredProducts,
        loading,
        searchQuery, setSearchQuery,
        selectedCategory, setSelectedCategory,
        sortBy, setSortBy,
        categories,
        resetFilters
    };

    return (
        <ShopContext.Provider value={value}>
            {children}
        </ShopContext.Provider>
    );
};

// eslint-disable-next-line react-refresh/only-export-components
export const useShop = () => useContext(ShopContext);

import React, { createContext, useContext, useState, useEffect } from 'react';

export const WishlistContext = createContext();

// eslint-disable-next-line react-refresh/only-export-components
export const useWishlist = () => {
    return useContext(WishlistContext);
};

export const WishlistProvider = ({ children }) => {
    const [wishlistItems, setWishlistItems] = useState(() => {
        try {
            const savedWishlist = localStorage.getItem('sharma-wishlist');
            return savedWishlist ? JSON.parse(savedWishlist) : [];
        } catch (error) {
            console.error("Failed to parse wishlist from local storage:", error);
            return [];
        }
    });

    useEffect(() => {
        try {
            localStorage.setItem('sharma-wishlist', JSON.stringify(wishlistItems));
        } catch (error) {
            console.error("Failed to save wishlist to local storage:", error);
        }
    }, [wishlistItems]);

    const addToWishlist = (product) => {
        setWishlistItems(prev => {
            if (prev.some(item => item.id === product.id)) return prev;
            return [...prev, product];
        });
    };

    const removeFromWishlist = (productId) => {
        setWishlistItems(prev => prev.filter(item => item.id !== productId));
    };

    const isInWishlist = (productId) => {
        return wishlistItems.some(item => item.id === productId);
    };

    const toggleWishlist = (product) => {
        if (isInWishlist(product.id)) {
            removeFromWishlist(product.id);
        } else {
            addToWishlist(product);
        }
    };

    const value = React.useMemo(() => ({
        wishlistItems,
        addToWishlist,
        removeFromWishlist,
        isInWishlist,
        toggleWishlist,
        wishlistCount: wishlistItems.length
    }), [wishlistItems]);

    return (
        <WishlistContext.Provider value={value}>
            {children}
        </WishlistContext.Provider>
    );
};

import { useState, useEffect } from 'react';
import { collection, query, getDocs, orderBy } from 'firebase/firestore';
import { db } from '../firebase/firebase';
import { useShop } from '../context/ShopContext';

export const useAnalytics = () => {
    const { products } = useShop();
    const [loading, setLoading] = useState(true);
    const [stats, setStats] = useState({
        totalRevenue: 0,
        totalOrders: 0,
        pendingOrders: 0,
        deliveredOrders: 0,
        monthlySales: [],
        topProducts: []
    });

    useEffect(() => {
        const fetchAnalytics = async () => {
            try {
                const ordersRef = collection(db, 'orders');
                const q = query(ordersRef, orderBy('createdAt', 'desc'));
                const snapshot = await getDocs(q);

                let revenue = 0;
                let pending = 0;
                let delivered = 0;
                const productSales = {}; // { pid: { name, qty, revenue } }
                const salesByDate = {}; // { "Jan 25": 500 }

                snapshot.docs.forEach(doc => {
                    const order = doc.data();
                    const amount = Number(order.total) || 0;

                    // KPI Counts
                    if (order.status !== 'Cancelled') {
                        revenue += amount;
                    }
                    if (order.status === 'Pending') pending++;
                    if (order.status === 'Delivered') delivered++;

                    // Chart Data (Group by Date)
                    let date;
                    try {
                        date = order.createdAt?.toDate ? order.createdAt.toDate() : new Date(order.createdAt);
                    } catch (e) {
                        date = new Date(); // Fallback to now if totally broken
                    }

                    if (!isNaN(date.getTime()) && order.status !== 'Cancelled') {
                        const dateKey = date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
                        salesByDate[dateKey] = (salesByDate[dateKey] || 0) + amount;
                    }

                    // Top Products
                    if (order.items && Array.isArray(order.items)) {
                        order.items.forEach(item => {
                            if (!productSales[item.id]) {
                                productSales[item.id] = {
                                    name: item.name,
                                    unitsSold: 0,
                                    revenue: 0,
                                    image: item.image || item.imageUrl
                                };
                            }
                            productSales[item.id].unitsSold += item.quantity || 1;
                            productSales[item.id].revenue += (item.price * (item.quantity || 1));
                        });
                    }
                });

                // Format Chart Data
                // Get last 7 days keys to ensure continuity or just use available data
                const chartData = Object.keys(salesByDate).map(date => ({
                    name: date,
                    sales: salesByDate[date]
                })).slice(0, 14).reverse(); // Just showing last available days roughly

                // Format Top Products
                const topProducts = Object.values(productSales)
                    .sort((a, b) => b.unitsSold - a.unitsSold)
                    .slice(0, 5);

                setStats({
                    totalRevenue: revenue,
                    totalOrders: snapshot.size,
                    pendingOrders: pending,
                    deliveredOrders: delivered,
                    monthlySales: chartData,
                    topProducts
                });

            } catch (error) {
                console.error("Error fetching analytics:", error);
            } finally {
                setLoading(false);
            }
        };

        fetchAnalytics();
    }, [products]);

    return { stats, loading };
};

import { useState, useEffect } from 'react';
import { useEngagement } from './useEngagement';

// Simple persistence for experiment assignments
const STORAGE_KEY = 'sharma_experiments';

export const useExperiments = () => {
    const { logEvent } = useEngagement();
    const [assignments, setAssignments] = useState(() => {
        try {
            return JSON.parse(localStorage.getItem(STORAGE_KEY)) || {};
        } catch {
            return {};
        }
    });

    const getVariant = (experimentId, variants = ['A', 'B']) => {
        // If already assigned, return it
        if (assignments[experimentId]) {
            return assignments[experimentId];
        }

        // Random assignment
        const randomVariant = variants[Math.floor(Math.random() * variants.length)];

        // Persist
        const newAssignments = { ...assignments, [experimentId]: randomVariant };
        setAssignments(newAssignments);
        localStorage.setItem(STORAGE_KEY, JSON.stringify(newAssignments));

        // Log Exposure
        logEvent('experiment_exposure', 'growth', { experimentId, variant: randomVariant });

        return randomVariant;
    };

    return { getVariant };
};

import { useState } from 'react';
import { collection, addDoc, getDocs, query, orderBy, serverTimestamp, doc, updateDoc, writeBatch } from 'firebase/firestore';
import { db } from '../firebase/firebase';

export const useRoadmap = () => {
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);

    const fetchRoadmap = async () => {
        setLoading(true);
        try {
            const q = query(collection(db, 'roadmap'), orderBy('createdAt', 'desc'));
            const snapshot = await getDocs(q);
            return snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
        } catch (err) {
            console.error("Error fetching roadmap:", err);
            setError(err.message);
            return [];
        } finally {
            setLoading(false);
        }
    };

    const saveRoadmapItems = async (items) => {
        setLoading(true);
        try {
            const batch = writeBatch(db);
            items.forEach(item => {
                const docRef = doc(collection(db, 'roadmap'));
                batch.set(docRef, {
                    ...item,
                    createdAt: serverTimestamp(),
                    status: item.status || 'Planned'
                });
            });
            await batch.commit();
            return true;
        } catch (err) {
            console.error("Error saving roadmap:", err);
            setError(err.message);
            return false;
        } finally {
            setLoading(false);
        }
    };

    const updateItemStatus = async (id, newStatus) => {
        try {
            await updateDoc(doc(db, 'roadmap', id), { status: newStatus });
            return true;
        } catch (err) {
            console.error("Error updating status:", err);
            return false;
        }
    };

    return { fetchRoadmap, saveRoadmapItems, updateItemStatus, loading, error };
};

import React from 'react';
import { Outlet, useLocation, useNavigate, Link } from 'react-router-dom';
