                                                className="w-full pl-12 pr-12 py-3.5 bg-slate-50 border border-slate-200 rounded-xl font-bold text-slate-900 outline-none focus:bg-white focus:ring-2 focus:ring-orange-500/20 focus:border-orange-500 transition-all placeholder:text-slate-300"
                                                placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
                                            />
                                            <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600">
                                                {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
                                            </button>
                                        </div>
                                    </div>

                                    {!isLogin && (
                                        <div className="space-y-1.5 animate-in">
                                            <label className="text-xs font-bold text-slate-500 uppercase tracking-wide ml-1">Confirm Password</label>
                                            <div className="relative group">
                                                <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-orange-500 transition-colors" size={20} />
                                                <input
                                                    type={showPassword ? "text" : "password"}
                                                    name="confirmPassword"
                                                    required
                                                    value={formData.confirmPassword}
                                                    onChange={handleChange}
                                                    className="w-full pl-12 pr-12 py-3.5 bg-slate-50 border border-slate-200 rounded-xl font-bold text-slate-900 outline-none focus:bg-white focus:ring-2 focus:ring-orange-500/20 focus:border-orange-500 transition-all placeholder:text-slate-300"
                                                    placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
                                                />
                                            </div>
                                        </div>
                                    )}

                                    <Button
                                        type="submit"
                                        isLoading={loading}
                                        className="w-full h-12 shadow-lg shadow-orange-500/30 mt-4 gap-2"
                                    >
                                        {isLogin ? 'Sign In' : 'Create Account'} <ArrowRight size={20} />
                                    </Button>
                                </form>
                            ) : (
                                <div className="space-y-6">
                                    {!otpSent ? (
                                        <div className="space-y-1.5">
                                            <label className="text-xs font-bold text-slate-500 uppercase tracking-wide ml-1">Mobile Number</label>
                                            <div className="relative group">
                                                <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-900 font-black">+91</div>
                                                <input
                                                    type="tel"
                                                    value={phoneNumber}
                                                    onChange={e => setPhoneNumber(e.target.value)}
                                                    className="w-full pl-14 pr-4 py-3.5 bg-slate-50 border border-slate-200 rounded-xl font-bold text-xl text-slate-900 outline-none focus:bg-white focus:ring-2 focus:ring-orange-500/20 focus:border-orange-500 transition-all placeholder:text-slate-300 tracking-wide"
                                                    placeholder="98765 43210"
                                                />
                                                <div id="recaptcha-container" />
                                            </div>
                                        </div>
                                    ) : (
                                        <div className="space-y-1.5">
                                            <label className="text-xs font-bold text-slate-500 uppercase tracking-wide ml-1">Enter OTP</label>
                                            <div className="relative group">
                                                <MessageSquare className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-orange-500 transition-colors" size={20} />
                                                <input
                                                    type="text"
                                                    value={otp}
                                                    onChange={e => setOtp(e.target.value)}
                                                    maxLength={6}
                                                    className="w-full pl-12 pr-4 py-3.5 bg-slate-50 border border-slate-200 rounded-xl font-bold text-2xl text-slate-900 outline-none focus:bg-white focus:ring-2 focus:ring-orange-500/20 focus:border-orange-500 transition-all placeholder:text-slate-300 tracking-[0.5em] text-center"
                                                    placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
                                                    autoFocus
                                                />
                                            </div>
                                            <Button
                                                onClick={handleVerifyOtp}
                                                isLoading={loading}
                                                className="w-full h-12 shadow-lg shadow-orange-500/30 mt-4 gap-2"
                                            >
                                                Verify OTP <ArrowRight size={20} />
                                            </Button>
                                        </div>
                                    )}
                                </div>
                            )}

                            <div className="relative my-8">
                                <div className="absolute inset-0 flex items-center">
                                    <div className="w-full border-t border-slate-200"></div>
                                </div>
                                <div className="relative flex justify-center text-sm">
                                    <span className="px-4 bg-white text-slate-400 font-bold uppercase tracking-wider text-xs">Or continue with</span>
                                </div>
                            </div>

                            <button
                                onClick={handleGoogleLogin}
                                disabled={loading}
                                className="w-full flex items-center justify-center gap-3 px-4 py-3.5 border border-slate-200 rounded-xl shadow-sm text-slate-700 font-bold bg-white hover:bg-slate-50 transition-all hover:border-slate-300 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-slate-200 group active:scale-[0.98]"
                            >
                                <svg className="h-5 w-5 shrink-0" viewBox="0 0 24 24">
                                    <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" fill="#4285F4" />
                                    <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853" />
                                    <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.84z" fill="#FBBC05" />
                                    <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335" />
                                </svg>
                                <span className="whitespace-nowrap">Continue with Google</span>
                            </button>

                            <div className="mt-8 text-center">
                                <button
                                    onClick={toggleMode}
                                    className="text-slate-600 font-bold hover:text-slate-900 transition-colors text-sm"
                                >
                                    {isLogin ? (
                                        <>
                                            New to Sharma Store? <span className="text-orange-600 hover:underline">Create an account</span>
                                        </>
                                    ) : (
                                        <>
                                            Already have an account? <span className="text-orange-600 hover:underline">Sign in</span>
                                        </>
                                    )}
                                </button>
                            </div>
                        </>
                    )}
                </div>
            </div>
        </div >
    );
};

export default Login;

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link, useLocation } from 'react-router-dom';
import { doc, getDoc } from 'firebase/firestore';
import { db } from '../firebase/firebase';
import { ShoppingCart, Zap, Heart, ShieldCheck, Truck, RefreshCw, Banknote, Star, Minus, Plus, Store, Gift, MessageCircle, ChevronRight, Share2 } from 'lucide-react';
import { useCart } from '../context/CartContext';
import { useAuth } from '../context/AuthContext';
import { useWishlist } from '../context/WishlistContext';
import { motion } from 'framer-motion';
import RecommendationRow from '../components/RecommendationRow';
import ReviewList from '../components/ReviewList';
import RecentlyViewed from '../components/RecentlyViewed';
import Button from '../components/Button';
import Card from '../components/common/Card';

// Helper for dynamic delivery date
const getDeliveryDate = () => {
    const date = new Date();
    date.setDate(date.getDate() + 2); // 2 days from now
    return date.toLocaleDateString("en-IN", { weekday: 'short', day: 'numeric', month: 'short' });
};

const ProductDetails = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const location = useLocation();
    const { addToCart, clearCart } = useCart();
    const { currentUser } = useAuth();
    const { toggleWishlist, isInWishlist } = useWishlist();

    const [product, setProduct] = useState(null);
    const [loading, setLoading] = useState(true);
    const [activeImage, setActiveImage] = useState(null);
    const [qty, setQty] = useState(1);
    const [isGift, setIsGift] = useState(false);

    useEffect(() => {
        if (!id) {
            setLoading(false);
            return;
        }

        const fetchProduct = async () => {
            try {
                const docRef = doc(db, "products", id);
                const docSnap = await getDoc(docRef);

                if (docSnap.exists()) {
                    const data = { ...docSnap.data(), id: docSnap.id };
                    setProduct(data);
                    setActiveImage(data.image || data.imageUrl || data.img || 'https://placehold.co/600x600?text=No+Image');
                } else {
                    // console.log("No such product!");
                }
            } catch (error) {
                console.error("Error fetching product:", error);
            } finally {
                setLoading(false);
            }
        };

        fetchProduct();
        window.scrollTo(0, 0);
    }, [id]);

    const handleBuyNow = () => {
        if (!product) return;

        if (!currentUser) {
            alert("Please log in to proceed with purchase.");
            navigate('/login', { state: { from: location } });
            return;
        }

        clearCart();
        addToCart({ ...product, isGift }, qty);
        navigate('/checkout/address');
    };

    const handleWhatsApp = () => {
        const message = `Hi Sharma Store, I am interested in ${product.name}. Is it available?`;
        const url = `https://wa.me/919021780559?text=${encodeURIComponent(message)}`;
        window.open(url, '_blank');
    };

    const handleQtyChange = (delta) => {
        setQty(prev => {
            const manualLimit = 10;
            const stockLimit = product?.stock || 10;
            const limit = Math.min(manualLimit, stockLimit);
            const newValue = prev + delta;
            return Math.max(1, Math.min(newValue, limit));
        });
    };

    if (loading) return <div className="min-h-screen bg-white flex items-center justify-center"><div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin"></div></div>;

    if (!product) return (
        <div className="w-full bg-white flex flex-col items-center justify-center p-8 text-center">
            <h2 className="text-2xl font-bold text-gray-900 mb-4">Product Not Found</h2>
            <button onClick={() => navigate('/')} className="px-6 py-3 bg-primary text-white rounded-xl font-bold">Go Home</button>
        </div>
    );

    const isWishlisted = isInWishlist(product.id);
    const discount = product.discountPercent || 30; // Use actual discount if available
    const mrp = product.mrp || Math.round(product.price * 1.42);

    return (
        <>
            <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                className="w-full bg-slate-50 font-sans text-gray-900 pb-8 page-enter"
            >
                <main className="max-w-7xl mx-auto px-4 sm:px-6 md:px-8 py-6">

                    {/* 1. Breadcrumb & Actions */}
                    <div className="flex items-center justify-between mb-6">
                        <nav className="flex items-center gap-2 text-sm text-gray-500 overflow-x-auto whitespace-nowrap pb-2 no-scrollbar">
                            <Link to="/" className="hover:text-primary transition-colors font-bold">Home</Link>
                            <ChevronRight size={14} />
                            <span className="text-gray-900 font-medium capitalize">{product.category || 'Shop'}</span>
                            <ChevronRight size={14} />
                            <span className="text-gray-400 truncate max-w-[150px]">{product.name}</span>
                        </nav>
                        <Button variant="ghost" size="icon-sm" className="rounded-full hover:bg-gray-100 text-gray-500">
                            <Share2 size={20} />
                        </Button>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8 lg:gap-12">
                        {/* Left: Gallery - Sticky on Desktop */}
                        <div className="space-y-4 md:sticky md:top-24 h-fit z-10">
                            <div className="relative aspect-square bg-white rounded-3xl overflow-hidden border border-gray-100 shadow-sm group">
                                <img
                                    src={activeImage}
                                    alt={product.name}
                                    className="w-full h-full object-contain p-8 group-hover:scale-105 transition-transform duration-500"
                                />
                                <button
                                    onClick={() => toggleWishlist(product)}
                                    className={`absolute top-4 right-4 p-3 rounded-full shadow-lg transition-all active:scale-95 ${isWishlisted ? 'bg-red-50 text-red-500 border-red-100' : 'bg-white text-gray-400 hover:text-red-500 border-gray-100'} border`}
                                >
                                    <Heart size={24} className={isWishlisted ? 'fill-current' : ''} />
                                </button>
                                {/* Zoom Hint */}
                                <div className="absolute bottom-4 left-1/2 -translate-x-1/2 bg-black/50 text-white text-[10px] px-3 py-1 rounded-full backdrop-blur-md opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none">
                                    Hover to Zoom
                                </div>
                            </div>
                        </div>

                        {/* Right: Info */}
                        <div className="flex flex-col">
                            {/* Product Title */}
                            <h1 className="text-2xl md:text-4xl font-black text-gray-900 leading-tight mb-2 tracking-tight">
                                {product.name}
                            </h1>

                            {/* Ratings */}
                            <div className="flex items-center gap-2 mb-6">
                                <div className="flex items-center bg-green-600 text-white px-2 py-0.5 rounded text-sm font-bold gap-1">
                                    {product.rating || 4.5} <Star size={12} fill="currentColor" />
                                </div>
                                <span className="text-sm font-medium text-gray-500">{product.reviewsCount || 120} Ratings & Reviews</span>
                            </div>

                            {/* Price Block */}
                            <Card className="mb-6 rounded-2xl border-gray-100">
                                <div className="flex items-baseline gap-3 mb-2">
                                    <span className="text-4xl font-black text-gray-900 tracking-tight">Γé╣{product.price}</span>
                                    <span className="text-lg text-gray-400 line-through decoration-2">Γé╣{mrp}</span>
                                    <span className="text-orange-600 text-lg font-bold">({discount}% OFF)</span>
                                </div>
                                <p className="text-xs text-green-600 font-bold mb-4">inclusive of all taxes</p>

                                {/* Stock Status */}
                                {product.stock < 10 && product.stock > 0 && (
                                    <p className="text-xs font-bold text-red-500 animate-pulse mb-0">
                                        Only {product.stock} left in stock!
                                    </p>
                                )}
                                {product.stock === 0 && (
                                    <p className="text-sm font-bold text-red-500 mb-0">
                                        Currently Unavailable
                                    </p>
                                )}
                            </Card>

                            {/* Desktop Actions Block */}
                            <div className="hidden md:grid grid-cols-[140px_1fr_1fr] gap-4 mb-8">
                                {/* Qty Selector */}
                                <div className="flex items-center justify-between bg-gray-100 rounded-xl px-2 h-14">
                                    <Button variant="ghost" size="icon-md" onClick={() => handleQtyChange(-1)} disabled={qty <= 1} className="w-10 h-10 rounded-lg hover:bg-white disabled:opacity-30"><Minus size={18} /></Button>
                                    <span className="font-bold text-lg">{qty}</span>
                                    <Button variant="ghost" size="icon-md" onClick={() => handleQtyChange(1)} disabled={qty >= 10} className="w-10 h-10 rounded-lg hover:bg-white disabled:opacity-30"><Plus size={18} /></Button>
                                </div>

                                <Button
                                    variant="secondary"
                                    onClick={() => {
                                        if (!currentUser) {
                                            alert("Please log in to add items to your cart.");
                                            navigate('/login', { state: { from: location } });
                                            return;
                                        }
                                        addToCart({ ...product, isGift }, qty);
                                    }}
                                    className="h-14 rounded-xl text-lg gap-2"
                                >
                                    <ShoppingCart size={20} /> Add to Cart
                                </Button>

                                <Button
                                    variant="primary"
                                    onClick={handleBuyNow}
                                    className="h-14 rounded-xl text-lg gap-2 shadow-lg shadow-orange-500/30"
                                >
                                    <Zap size={20} fill="currentColor" /> Buy Now
                                </Button>
                            </div>

                            {/* Quick Trust Info */}
                            <div className="grid grid-cols-4 gap-2 mb-8 border-b border-gray-200 pb-8">
                                {[
                                    { icon: Truck, label: "Fast Delivery", sub: `Get it by ${getDeliveryDate()}` },
                                    { icon: ShieldCheck, label: "Genuine", sub: "100% Verified" },
                                    { icon: RefreshCw, label: "Easy Return", sub: "7 Days" },
                                    { icon: Banknote, label: "COD", sub: "Available" }
                                ].map((item, i) => (
                                    <div key={i} className="flex flex-col items-center text-center p-2 rounded-xl hover:bg-white transition-colors">
                                        <div className="mb-2 text-primary bg-primary/10 p-2 rounded-full">
                                            <item.icon size={20} />
                                        </div>
                                        <span className="text-xs font-bold text-gray-900">{item.label}</span>
                                        <span className="text-[10px] text-gray-500">{item.sub}</span>
                                    </div>
                                ))}
                            </div>

                            {/* Sections */}
                            <div className="space-y-8">
                                {/* Description */}
                                <section>
                                    <h3 className="font-black text-gray-900 mb-3 text-lg flex items-center gap-2">
                                        Product Details
                                    </h3>
                                    <p className="text-gray-600 leading-relaxed text-sm md:text-base">
                                        {product.description || "Experience premium quality with this meticulously crafted product. Designed for durability and style, it fits perfectly into your lifestyle. Whether for personal use or as a thoughtful gift, this item stands out with its superior finish and attention to detail."}
                                    </p>

                                    {/* Mock Highlights */}
                                    <ul className="mt-4 space-y-2">
                                        {[
                                            "Premium quality material for long-lasting usage",
                                            "Modern and aesthetic design",
                                            "Perfect for gifting on special occasions",
                                            "Value for money deal"
                                        ].map((pt, i) => (
                                            <li key={i} className="flex items-start gap-2 text-sm text-gray-700">
                                                <div className="w-1.5 h-1.5 rounded-full bg-gray-400 mt-1.5 shrink-0"></div>
                                                {pt}
                                            </li>
                                        ))}
                                    </ul>
                                </section>

                                {/* Gift Option */}
                                <section className="bg-purple-50 rounded-2xl p-5 border border-purple-100 flex items-start gap-4">
                                    <div className="bg-white p-3 rounded-full text-purple-600 shadow-sm">
                                        <Gift size={24} />
                                    </div>
                                    <div className="flex-1">
                                        <div className="flex justify-between items-center mb-1">
                                            <h4 className="font-bold text-purple-900">Gifting this item?</h4>
                                            <div
                                                className={`w-12 h-7 rounded-full p-1 cursor-pointer transition-colors ${isGift ? 'bg-purple-600' : 'bg-gray-300'}`}
                                                onClick={() => setIsGift(!isGift)}
                                            >
                                                <motion.div
                                                    className="w-5 h-5 bg-white rounded-full shadow-sm"
                                                    animate={{ x: isGift ? 20 : 0 }}
                                                />
                                            </div>
                                        </div>
                                        <p className="text-xs text-purple-700 leading-relaxed">
                                            Add gift wrap and a personalized message at checkout. We'll make sure it looks special!
                                        </p>
                                    </div>
                                </section>

                                {/* Reviews */}
                                <ReviewList reviewsCount={product.reviewsCount || 120} rating={product.rating || 4.5} />
                            </div>
                        </div>
                    </div>

                    <div className="mt-20">
                        <RecentlyViewed currentProductId={product.id} />
                        <RecommendationRow source="product" currentProduct={product} />
                    </div>
                </main>
            </motion.div>

            {/* FIXED MOBILE FOOTER ACTIONS */}
            <div className="fixed bottom-0 left-0 w-full bg-white border-t border-gray-200 p-3 pb-safe z-50 md:hidden shadow-[0_-4px_20px_rgba(0,0,0,0.1)]">
                <div className="flex gap-3 h-12">
                    {/* WhatsApp/Chat - Small */}
                    <Button onClick={handleWhatsApp} variant="white" className="w-12 h-full rounded-lg bg-green-50 text-green-600 border border-green-100 p-0 flex items-center justify-center shrink-0 shadow-none hover:bg-green-100">
                        <MessageCircle size={24} />
                    </Button>

                    {/* Add to Cart - Secondary */}
                    <Button
                        variant="secondary"
                        onClick={() => {
                            if (!currentUser) {
                                alert("Please log in to add items to your cart.");
                                navigate('/login', { state: { from: location } });
                                return;
                            }
                            addToCart({ ...product, isGift }, qty);
                        }}
                        className="flex-1 rounded-lg text-sm"
                    >
                        Add to Cart
                    </Button>

                    {/* Buy Now - Primary & Prominent */}
                    <Button
                        variant="primary"
                        onClick={handleBuyNow}
                        className="flex-1 rounded-lg text-sm gap-1 shadow-lg shadow-orange-500/30"
                    >
                        <Zap size={16} fill="currentColor" /> Buy Now
                    </Button>
                </div>
            </div>
        </>
    );
};

export default ProductDetails;

import React, { useState } from 'react';
import { useLoyalty } from '../context/LoyaltyContext';
import { Sparkles, Gift, Tag, Lock, CheckCircle, ArrowLeft, Loader2 } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { Link, useNavigate } from 'react-router-dom';
import Button from '../components/Button';
import Card from '../components/common/Card';

const Redeem = () => {
    const { coins, redeemCoins } = useLoyalty();
    const navigate = useNavigate();
    const [loading, setLoading] = useState(false);
    const [successItem, setSuccessItem] = useState(null);

    const rewards = [
        { id: 1, title: 'Limited Edition Notebook', cost: 2500, image: 'https://images.unsplash.com/photo-1544816155-12df9643f363?auto=format&fit=crop&q=80&w=600', type: 'exclusive' },
        { id: 2, title: 'Premium Gel Pen Set', cost: 1200, image: 'https://images.unsplash.com/photo-1585336261022-680e295ce3fe?auto=format&fit=crop&q=80&w=600', type: 'exclusive' },
        { id: 3, title: 'Sharma Store Cap', cost: 800, image: 'https://images.unsplash.com/photo-1575428652377-a2d80e2277fc?auto=format&fit=crop&q=80&w=600', type: 'exclusive' },
        { id: 4, title: 'Γé╣500 Off Voucher', cost: 500, type: 'voucher', code: 'SHARMA500' },
        { id: 5, title: 'Γé╣100 Off Voucher', cost: 100, type: 'voucher', code: 'SHARMA100' },
        { id: 6, title: 'Free Delivery', cost: 250, type: 'voucher', code: 'FREEDEL' },
    ];

    const handleRedeem = (item) => {
        if (coins < item.cost) return;
        setLoading(true);
        setTimeout(() => {
            const success = redeemCoins(item.cost, `Redeemed: ${item.title}`);
            setLoading(false);
            if (success) setSuccessItem(item);
        }, 1500);
    };

    return (
        <div className="w-full bg-slate-50 pb-8 bg-[radial-gradient(#e5e7eb_1px,transparent_1px)] [background-size:16px_16px]">
            <div className="max-w-6xl mx-auto">
                {/* Header */}
                <div className="flex items-center justify-between mb-8">
                    <div className="flex items-center gap-4">
                        <Link to="/profile" className="p-3 bg-white rounded-xl hover:bg-gray-50 transition-colors shadow-sm text-gray-600">
                            <ArrowLeft size={20} />
                        </Link>
                        <div>
                            <h1 className="text-3xl font-black text-gray-900 tracking-tight">Redeem Coins</h1>
                            <p className="text-sm font-bold text-gray-500">Spend your hard-earned Sharma Coins</p>
                        </div>
                    </div>
                    <div className="bg-white px-4 py-2 rounded-xl flex items-center gap-2 border border-blue-100 shadow-sm">
                        <Sparkles className="text-primary size-5" fill="currentColor" />
                        <span className="font-black text-lg text-primary">{coins.toLocaleString()}</span>
                    </div>
                </div>

                {/* Exclusive Rewards Section */}
                <div className="mb-12">
                    <h2 className="text-xl font-black text-gray-900 mb-6 flex items-center gap-2">
                        <Gift className="text-purple-600" /> Exclusive Gear
                    </h2>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        {rewards.filter(r => r.type === 'exclusive').map(item => (
                            <div key={item.id} className="frosted-paper rounded-3xl overflow-hidden border border-white/60 shadow-lg group hover:scale-[1.02] transition-transform">
                                <div className="h-48 bg-gray-100 relative">
                                    <img src={item.image} alt={item.title} className="w-full h-full object-cover" />
                                    {coins < item.cost && (
                                        <div className="absolute inset-0 bg-black/50 backdrop-blur-[2px] flex items-center justify-center">
                                            <div className="bg-black/80 text-white px-4 py-2 rounded-full flex items-center gap-2 text-xs font-bold">
                                                <Lock size={12} /> Locked
                                            </div>
                                        </div>
                                    )}
                                </div>
                                <div className="p-6">
                                    <h3 className="font-bold text-gray-900 mb-1">{item.title}</h3>
                                    <div className="flex items-center justify-between mt-4">
                                        <span className="text-primary font-black text-lg flex items-center gap-1">
                                            {item.cost} <span className="text-xs font-bold text-gray-400">Coins</span>
                                        </span>
                                        <Button
                                            onClick={() => handleRedeem(item)}
                                            disabled={coins < item.cost || loading}
                                            variant={coins >= item.cost ? 'primary' : 'gray'}
                                            className={`px-4 py-2 rounded-xl text-sm font-bold transition-all shadow-lg ${coins < item.cost ? 'bg-gray-100 text-gray-400 cursor-not-allowed shadow-none' : 'bg-gray-900 hover:bg-black text-white'}`}
                                        >
                                            {coins >= item.cost ? 'Claim' : 'Need More'}
                                        </Button>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Vouchers Section */}
                <div>
                    <h2 className="text-xl font-black text-gray-900 mb-6 flex items-center gap-2">
                        <Tag className="text-blue-600" /> Vouchers & Coupons
                    </h2>
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {rewards.filter(r => r.type === 'voucher').map(item => (
                            <Card key={item.id} className="bg-white rounded-3xl p-6 border-2 border-dashed border-gray-200 relative overflow-hidden group hover:border-blue-200 transition-colors shadow-none hover:shadow-sm">
                                <div className="absolute -left-3 top-1/2 -translate-y-1/2 w-6 h-6 bg-slate-50 rounded-full border border-gray-200"></div>
                                <div className="absolute -right-3 top-1/2 -translate-y-1/2 w-6 h-6 bg-slate-50 rounded-full border border-gray-200"></div>

                                <div className="flex justify-between items-start mb-4">
                                    <div className="bg-blue-50 text-blue-600 p-3 rounded-xl">
                                        <Tag size={24} />
                                    </div>
                                    <span className="font-black text-lg text-gray-900">{item.cost} Coins</span>
                                </div>

                                <h3 className="font-bold text-gray-900 text-lg mb-2">{item.title}</h3>
                                <p className="text-xs text-gray-500 font-medium mb-6">Valid on all orders above Γé╣999. One time use only.</p>

                                <Button
                                    onClick={() => handleRedeem(item)}
                                    disabled={coins < item.cost || loading}
                                    className={`w-full py-3 rounded-xl font-bold transition-all ${coins >= item.cost
                                        ? 'bg-blue-600 text-white hover:bg-blue-700 shadow-lg shadow-blue-200'
                                        : 'bg-gray-100 text-gray-400 cursor-not-allowed shadow-none'
                                        }`}
                                >
                                    Redeem Voucher
                                </Button>
                            </Card>
                        ))}
                    </div>
                </div>
            </div>

            {/* Success Modal */}
            <AnimatePresence>
                {successItem && (
                    <motion.div
                        initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
                        className="fixed inset-0 z-[100] bg-black/80 backdrop-blur-sm flex items-center justify-center p-4"
                    >
                        <motion.div
                            initial={{ scale: 0.5, rotate: -10 }} animate={{ scale: 1, rotate: 0 }}
                            className="bg-white w-full max-w-sm rounded-3xl p-8 text-center relative overflow-hidden"
                        >
                            <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-yellow-200 via-white to-white opacity-50"></div>
                            <div className="relative z-10">
                                <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6 text-green-600 shadow-inner">
                                    <CheckCircle size={40} strokeWidth={3} />
                                </div>
                                <h2 className="text-2xl font-black text-gray-900 mb-2">You Got It!</h2>
                                <p className="text-gray-500 font-bold mb-6">You successfully redeemed <br /> <span className="text-primary">{successItem.title}</span></p>

                                {successItem.type === 'voucher' && (
                                    <div className="bg-gray-100 p-4 rounded-xl border-dashed border-2 border-gray-300 mb-6">
                                        <p className="text-xs font-bold text-gray-400 uppercase">Your Code</p>
                                        <p className="text-2xl font-black text-gray-900 tracking-widest">{successItem.code}</p>
                                    </div>
                                )}

                                <button onClick={() => setSuccessItem(null)} className="w-full py-3 bg-gray-900 text-white font-bold rounded-xl shadow-lg">Awesome!</button>
                            </div>
                        </motion.div>
                    </motion.div>
                )}
            </AnimatePresence>

            {loading && (
                <div className="fixed inset-0 z-[110] flex items-center justify-center bg-transparent">
                    <div className="bg-white/90 backdrop-blur px-6 py-4 rounded-2xl shadow-xl flex items-center gap-3">
                        <Loader2 className="animate-spin text-primary" />
                        <span className="font-bold text-gray-900">Processing...</span>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Redeem;

import React from 'react';
// removed unused firebase imports
import ProductCard from '../components/ProductCard';
import { Search } from 'lucide-react';
import { useShop } from '../context/ShopContext';
import { motion } from 'framer-motion';
