import React, { useState, useEffect } from 'react';
import { useFeedback } from '../../hooks/useFeedback';
import { analyzeFeedback, analyzeSentimentBatch } from '../../services/aiService';
import { Loader2, Sparkles, Bug, Lightbulb, Star, RefreshCw, MessageSquare, TrendingUp } from 'lucide-react';
import SentimentCharts from '../../components/admin/SentimentCharts';

const AdminFeedback = () => {
    const { getFeedback, updateFeedbackSentiment } = useFeedback();
    const [feedbackList, setFeedbackList] = useState([]);
    const [loading, setLoading] = useState(true);
    const [analyzing, setAnalyzing] = useState(false);
    const [insights, setInsights] = useState(null);
    const [sentimentLoading, setSentimentLoading] = useState(false);

    const fetchFeedback = React.useCallback(async () => {
        setLoading(true);
        const data = await getFeedback();
        setFeedbackList(data);
        setLoading(false);
    }, [getFeedback]);

    useEffect(() => {
        fetchFeedback();
    }, [fetchFeedback]);

    const handleBatchSentiment = async () => {
        setSentimentLoading(true);
        // Analzye all (or just unanalyzed)
        const toAnalyze = feedbackList.filter(f => !f.sentiment);
        if (toAnalyze.length === 0) {
            alert("All items already analyzed! (Or no feedback)");
            setSentimentLoading(false);
            return;
        }

        const results = await analyzeSentimentBatch(toAnalyze);
        if (Object.keys(results).length > 0) {
            await updateFeedbackSentiment(results);
            await fetchFeedback(); // Refresh UI
        }
        setSentimentLoading(false);
    };

    const handleAnalyze = async () => {
        setAnalyzing(true);
        const result = await analyzeFeedback(feedbackList);
        setInsights(result);
        setAnalyzing(false);
    };

    const getIcon = (type) => {
        switch (type) {
            case 'bug': return <Bug size={18} className="text-red-500" />;
            case 'suggestion': return <Lightbulb size={18} className="text-blue-500" />;
            case 'review': return <Star size={18} className="text-yellow-500" />;
            default: return <MessageSquare size={18} className="text-gray-500" />;
        }
    };

    const getUrgencyBadge = (urgency) => {
        const colors = { Low: 'bg-green-100 text-green-700', Medium: 'bg-yellow-100 text-yellow-700', High: 'bg-red-100 text-red-700' };
        return urgency ? <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${colors[urgency] || 'bg-gray-100'}`}>{urgency}</span> : null;
    };

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-20">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-black text-gray-900">User Feedback</h1>
                    <p className="text-gray-500">Listen to your customers and improve.</p>
                </div>
                <div className="flex gap-2">
                    <button
                        onClick={handleBatchSentiment}
                        disabled={sentimentLoading}
                        className="px-4 py-2 bg-white rounded-xl shadow-sm text-gray-600 hover:text-blue-600 font-bold text-sm flex items-center gap-2 transition-all"
                    >
                        {sentimentLoading ? <Loader2 size={16} className="animate-spin" /> : <TrendingUp size={16} />}
                        Analyze Sentiment
                    </button>
                    <button
                        onClick={fetchFeedback}
                        className="p-2 bg-white rounded-xl shadow-sm text-gray-500 hover:text-orange-500 transition-colors"
                    >
                        <RefreshCw size={20} />
                    </button>
                </div>
            </div>

            {/* Sentiment Charts */}
            <SentimentCharts feedbackList={feedbackList} />

            {/* AI Insights Card */}
            <div className="bg-gradient-to-br from-slate-900 to-slate-800 rounded-3xl p-6 md:p-8 text-white shadow-xl relative overflow-hidden">
                <div className="absolute top-0 right-0 p-32 bg-orange-500/20 rounded-full blur-3xl -translate-y-16 translate-x-16"></div>

                <div className="relative z-10">
                    <div className="flex items-center justify-between mb-6">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 bg-white/10 rounded-xl flex items-center justify-center backdrop-blur-md">
                                <Sparkles size={20} className="text-orange-400" />
                            </div>
                            <h2 className="text-xl font-bold">AI Summary</h2>
                        </div>
                        <button
                            onClick={handleAnalyze}
                            disabled={analyzing || feedbackList.length === 0}
                            className="px-4 py-2 bg-white/10 hover:bg-white/20 hover:text-orange-300 disabled:opacity-50 disabled:cursor-not-allowed rounded-xl text-sm font-bold transition-all flex items-center gap-2"
                        >
                            {analyzing ? <Loader2 size={16} className="animate-spin" /> : <Sparkles size={16} />}
                            {analyzing ? 'Reasoning...' : 'Generate New Summary'}
                        </button>
                    </div>

                    {insights ? (
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 animate-in slide-in-from-bottom-4 duration-500">
                            <div className="bg-white/5 p-4 rounded-2xl border border-white/10">
                                <h3 className="text-orange-300 font-bold text-sm uppercase tracking-wider mb-3">Top Issues</h3>
                                <ul className="space-y-2 text-sm text-gray-300">
                                    {insights.topIssues?.map((issue, i) => <li key={i} className="flex gap-2"><span className="text-orange-500">ΓÇó</span> {issue}</li>)}
                                </ul>
                            </div>
                            <div className="bg-white/5 p-4 rounded-2xl border border-white/10">
                                <h3 className="text-green-300 font-bold text-sm uppercase tracking-wider mb-3">Suggested Improvements</h3>
                                <ul className="space-y-2 text-sm text-gray-300">
                                    {insights.improvements?.map((imp, i) => <li key={i} className="flex gap-2"><span className="text-green-500">ΓÇó</span> {imp}</li>)}
                                </ul>
                            </div>
                            <div className="bg-white/5 p-4 rounded-2xl border border-white/10 flex flex-col items-center justify-center">
                                <h3 className="text-blue-300 font-bold text-sm uppercase tracking-wider mb-2">Overall Sentiment</h3>
                                <span className="text-3xl font-black">{insights.sentiment}</span>
                            </div>
                        </div>
                    ) : (
                        <div className="text-center py-8 text-gray-400 text-sm">
                            {analyzing ? "Reading feedback..." : "Click 'Generate Summary' to let AI analyze themes."}
                        </div>
                    )}
                </div>
            </div>

            {/* Feedback List */}
            <div className="bg-white/50 backdrop-blur-xl border border-white/60 rounded-3xl p-1 overflow-hidden">
                {loading ? (
                    <div className="p-12 flex justify-center"><Loader2 size={32} className="animate-spin text-orange-500" /></div>
                ) : feedbackList.length === 0 ? (
                    <div className="p-12 text-center text-gray-500 font-medium">No feedback received yet.</div>
                ) : (
                    <table className="w-full text-left">
                        <thead className="bg-gray-50/50 border-b border-gray-100 text-xs font-bold text-gray-500 uppercase tracking-wider">
                            <tr>
                                <th className="p-4">Type</th>
                                <th className="p-4">Message</th>
                                <th className="p-4 hidden md:table-cell">Page</th>
                                <th className="p-4 hidden md:table-cell">Sentiment</th>
                                <th className="p-4 hidden md:table-cell">Date</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {feedbackList.map((feedback) => (
                                <tr key={feedback.id} className="hover:bg-white/80 transition-colors group">
                                    <td className="p-4">
                                        <div className="flex items-center gap-2">
                                            <div className={`w-8 h-8 rounded-lg flex items-center justify-center bg-gray-100 group-hover:bg-white transition-colors`}>
                                                {getIcon(feedback.type)}
                                            </div>
                                            <div className="flex flex-col">
                                                <span className="font-bold text-sm capitalize text-gray-700">{feedback.type}</span>
                                                {getUrgencyBadge(feedback.urgency)}
                                            </div>
                                        </div>
                                    </td>
                                    <td className="p-4">
                                        <p className="text-gray-900 font-medium text-sm line-clamp-2">{feedback.message}</p>
                                        {feedback.reason && <p className="text-xs text-gray-400 mt-1">AI Note: {feedback.reason}</p>}
                                    </td>
                                    <td className="p-4 hidden md:table-cell">
                                        <code className="text-xs bg-gray-100 px-2 py-1 rounded text-gray-600 block w-fit max-w-[150px] truncate">{feedback.page}</code>
                                    </td>
                                    <td className="p-4 hidden md:table-cell">
                                        {feedback.sentiment ? (
                                            <span className={`text-xs font-bold ${feedback.sentiment === 'Positive' ? 'text-green-600' :
                                                    feedback.sentiment === 'Negative' ? 'text-red-500' : 'text-gray-500'
                                                }`}>
                                                {feedback.sentiment}
                                            </span>
                                        ) : <span className="text-xs text-gray-300">-</span>}
                                    </td>
                                    <td className="p-4 hidden md:table-cell text-sm text-gray-500">
                                        {feedback.createdAt?.seconds ? new Date(feedback.createdAt.seconds * 1000).toLocaleDateString() : 'Just now'}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                )}
            </div>
        </div>
    );
};

export default AdminFeedback;

import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { doc, getDoc, updateDoc, increment } from 'firebase/firestore';
import { db } from '../../firebase/firebase';
import { ArrowLeft, Package, User, MapPin, Phone, CreditCard, ChevronDown, AlertTriangle, CheckCircle, Truck, Clock, XCircle } from 'lucide-react';
import Button from '../../components/Button';
import Card from '../../components/common/Card';

const AdminOrderDetails = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const [order, setOrder] = useState(null);
    const [loading, setLoading] = useState(true);
    const [updating, setUpdating] = useState(false);

    useEffect(() => {
        const fetchOrder = async () => {
            try {
                const docRef = doc(db, 'orders', id);
                const docSnap = await getDoc(docRef);
                if (docSnap.exists()) {
                    setOrder({ id: docSnap.id, ...docSnap.data() });
                }
            } catch (error) {
                console.error("Error fetching order:", error);
            } finally {
                setLoading(false);
            }
        };
        fetchOrder();
    }, [id]);

    const handleStatusChange = async (newStatus) => {
        setUpdating(true);
        try {
            await updateDoc(doc(db, 'orders', id), { status: newStatus });
            setOrder(prev => ({ ...prev, status: newStatus }));
        } catch (error) {
            console.error("Error updating status:", error);
            alert("Failed to update status");
        } finally {
            setUpdating(false);
        }
    };

    const getStatusColor = (status) => {
        switch (status) {
            case 'Delivered': return 'bg-green-100 text-green-700 border-green-200';
            case 'Cancelled': return 'bg-red-100 text-red-700 border-red-200';
            case 'Shipped': return 'bg-blue-100 text-blue-700 border-blue-200';
            case 'Processing': return 'bg-orange-100 text-orange-700 border-orange-200';
            default: return 'bg-yellow-100 text-yellow-700 border-yellow-200';
        }
    };

    if (loading) return (
        <div className="flex h-[60vh] items-center justify-center">
            <div className="animate-spin rounded-full h-12 w-12 border-4 border-orange-200 border-t-orange-600"></div>
        </div>
    );

    if (!order) return <div className="text-center p-10 font-bold text-gray-500">Order not found</div>;

    return (
        <div className="max-w-5xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div className="flex items-center gap-4">
                    <Button
                        variant="white"
                        size="icon"
                        onClick={() => navigate('/admin/orders')}
                        className="shadow-sm border-gray-200 text-gray-500 hover:text-gray-900"
                    >
                        <ArrowLeft size={20} />
                    </Button>
                    <div>
                        <div className="flex items-center gap-3">
                            <h1 className="text-3xl font-black text-gray-900 tracking-tight">Order #{order.orderId || order.id.slice(0, 8)}</h1>
                            <span className={`px-3 py-1 rounded-full text-xs font-black uppercase tracking-wide border ${getStatusColor(order.status)}`}>
                                {order.status}
                            </span>
                        </div>
                        <p className="text-sm font-bold text-gray-400 mt-1">
                            Placed on {order.createdAt ? new Date(order.createdAt.seconds * 1000).toLocaleString() : 'N/A'}
                        </p>
                    </div>
                </div>

                <div className="flex items-center gap-3 bg-white p-1.5 rounded-2xl border border-gray-100 shadow-sm">
                    {['Pending', 'Processing', 'Shipped', 'Delivered', 'Cancelled'].map((status) => (
                        <button
                            key={status}
                            onClick={() => handleStatusChange(status)}
                            disabled={updating}
                            className={`px-4 py-2 rounded-xl text-xs font-black uppercase tracking-wide transition-all ${order.status === status
                                ? 'bg-gray-900 text-white shadow-md scale-105'
                                : 'text-gray-500 hover:bg-gray-50'
                                }`}
                        >
                            {status}
                        </button>
                    ))}
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {/* Left: Order Items */}
                <div className="md:col-span-2 space-y-6">
                    <Card className="p-0 overflow-hidden border-orange-100/50">
                        <div className="px-6 py-4 border-b border-gray-100 bg-orange-50/30 flex items-center gap-2">
                            <Package className="text-orange-500" size={20} />
                            <h2 className="font-black text-gray-900">Order Items</h2>
                        </div>
                        <div className="p-6 space-y-6">
                            {order.items?.map((item, index) => (
                                <div key={index} className="flex gap-4 group">
                                    <div className="w-20 h-20 rounded-xl bg-gray-100 overflow-hidden border border-gray-200 shrink-0">
                                        <img src={item.image || item.imageUrl || 'https://placehold.co/100'} alt={item.name} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <h3 className="font-bold text-gray-900 text-lg truncate">{item.name}</h3>
                                        <p className="text-sm font-medium text-gray-500">Category: {item.category}</p>
                                        <div className="flex items-center gap-4 mt-2">
                                            <span className="text-xs font-bold bg-gray-100 text-gray-600 px-2 py-1 rounded-lg">Qty: {item.quantity || 1}</span>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <p className="font-black text-gray-900 text-lg">Γé╣{item.price * (item.quantity || 1)}</p>
                                        <p className="text-xs text-gray-400 font-medium">Γé╣{item.price} / unit</p>
                                    </div>
                                </div>
                            ))}
                        </div>
                        <div className="bg-gray-50 p-6 flex justify-between items-center border-t border-gray-100">
                            <span className="font-bold text-gray-500 uppercase tracking-widest text-xs">Total Order Value</span>
                            <span className="text-3xl font-black text-gray-900 tracking-tight">Γé╣{order.total}</span>
                        </div>
                    </Card>
                </div>

                {/* Right: Customer Info */}
                <div className="space-y-6">
                    <Card className="p-6 space-y-6">
                        <div>
                            <h2 className="text-sm font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                                <User size={16} /> Customer Details
                            </h2>
                            <div className="flex items-center gap-4 mb-4">
                                <div className="w-12 h-12 rounded-full bg-blue-50 text-blue-600 flex items-center justify-center font-black text-lg">
                                    {(order.customer?.name || order.address?.fullName || "G")[0]}
                                </div>
                                <div>
                                    <p className="font-bold text-gray-900">{order.customer?.name || order.address?.fullName || "Guest User"}</p>
                                    <p className="text-xs font-bold text-gray-500">{order.customer?.email || order.userEmail || order.email}</p>
                                </div>
                            </div>
                            {order.address?.phoneNumber && (
                                <div className="flex items-center gap-3 text-sm font-bold text-gray-600 bg-gray-50 p-3 rounded-xl">
                                    <Phone size={16} /> {order.address.phoneNumber}
                                </div>
                            )}
                        </div>

                        <div className="border-t border-gray-100 pt-6">
                            <h2 className="text-sm font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                                <MapPin size={16} /> Shipping Address
                            </h2>
                            <p className="text-sm font-medium text-gray-700 leading-relaxed bg-gray-50 p-4 rounded-xl border border-gray-100">
                                {order.address ? (
                                    <>
                                        {order.address.addressLine1}, <br />
                                        {order.address.city}, {order.address.state} <br />
                                        {order.address.pincode}
                                    </>
                                ) : "No address provided"}
                            </p>
                        </div>

                        <div className="border-t border-gray-100 pt-6">
                            <h2 className="text-sm font-bold text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                                <CreditCard size={16} /> Payment Info
                            </h2>
                            <div className={`p-4 rounded-xl border flex items-center justify-between ${order.isPaid ? 'bg-green-50 border-green-100' : 'bg-orange-50 border-orange-100'}`}>
                                <span className={`text-xs font-black uppercase ${order.isPaid ? 'text-green-700' : 'text-orange-700'}`}>
                                    {order.isPaid ? 'Paid Online' : 'Cash on Delivery'}
                                </span>
                                {order.isPaid ? <CheckCircle size={18} className="text-green-600" /> : <Clock size={18} className="text-orange-600" />}
                            </div>
                        </div>
                    </Card>

                    {/* Quick Actions */}
                    <Card className="p-6">
                        <h2 className="text-sm font-bold text-gray-400 uppercase tracking-widest mb-4">Quick Actions</h2>
                        <Button
                            onClick={() => window.print()}
                            variant="secondary"
                            className="w-full mb-3"
                        >
                            Print Invoice
                        </Button>
                        {order.status !== 'Cancelled' && (
                            <Button
                                onClick={() => {
                                    if (window.confirm('Are you sure you want to cancel this order?')) {
                                        handleStatusChange('Cancelled');
                                    }
                                }}
                                className="w-full bg-red-50 text-red-600 hover:bg-red-100 border-red-100"
                            >
                                Cancel Order
                            </Button>
                        )}
                    </Card>
                </div>
            </div>
        </div>
    );
};

export default AdminOrderDetails;

import React, { useState, useEffect } from 'react';
import { useRoadmap } from '../../hooks/useRoadmap';
import { useFeedback } from '../../hooks/useFeedback';
import { generateRoadmap } from '../../services/aiService';
import { Loader2, Sparkles, Map, AlertCircle, CheckCircle2, Clock } from 'lucide-react';

const AdminRoadmap = () => {
    const { fetchRoadmap, saveRoadmapItems, updateItemStatus } = useRoadmap();
    const { getFeedback } = useFeedback();
    const [roadmap, setRoadmap] = useState([]);
    const [loading, setLoading] = useState(true);
    const [generating, setGenerating] = useState(false);

    const loadData = React.useCallback(async () => {
        setLoading(true);
        const data = await fetchRoadmap();
        setRoadmap(data);
        setLoading(false);
    }, [fetchRoadmap]);

    useEffect(() => {
        loadData();
    }, [loadData]);

    const handleGenerate = async () => {
        setGenerating(true);
        try {
            // 1. Get Feedback
            const feedback = await getFeedback();
            // 2. Generate Roadmap via AI
            const newItems = await generateRoadmap(feedback);
            // 3. Save to DB
            if (newItems.length > 0) {
                await saveRoadmapItems(newItems);
                await loadData(); // Reload to see new items
            } else {
                alert("AI couldn't generate any new items (or no feedback found).");
            }
        } catch (error) {
            console.error(error);
            alert("Failed to generate roadmap.");
        } finally {
            setGenerating(false);
        }
    };

    const handleStatusChange = async (id, status) => {
        await updateItemStatus(id, status);
        // Optimistic update locally
        setRoadmap(prev => prev.map(item => item.id === id ? { ...item, status } : item));
    };

    const PriorityColumn = ({ title, priority, icon: Icon, color }) => {
        const items = roadmap.filter(i => i.priority === priority);
        return (
            <div className="flex-1 min-w-[300px] bg-slate-50/50 rounded-3xl p-4 border border-slate-100 flex flex-col">
                <div className={`flex items-center gap-2 mb-4 p-2 rounded-xl ${color} bg-opacity-10 text-${color.split('-')[1]}-600`}>
                    <Icon size={18} className={`text-${color.split('-')[1]}-500`} />
                    <h3 className="font-bold text-sm uppercase tracking-wider">{title}</h3>
                    <span className="ml-auto bg-white px-2 py-0.5 rounded-md text-xs font-black shadow-sm">{items.length}</span>
                </div>

                <div className="space-y-3 flex-1 overflow-y-auto pr-2 scrollbar-thin">
                    {items.length === 0 && (
                        <div className="text-center py-10 text-gray-400 text-sm border-2 border-dashed border-gray-100 rounded-xl">
                            No {title.toLowerCase()} items.
                        </div>
                    )}
                    {items.map(item => (
                        <div key={item.id} className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm hover:shadow-md transition-shadow group relative">
                            {/* Status Badge */}
                            <div className="flex justify-between items-start mb-2">
                                <span className={`text-[10px] font-bold px-2 py-1 rounded-md uppercase tracking-wide
                                    ${item.status === 'Completed' ? 'bg-green-100 text-green-700' :
                                        item.status === 'In Progress' ? 'bg-blue-100 text-blue-700' :
                                            'bg-gray-100 text-gray-600'}`}>
                                    {item.status}
                                </span>
                                <select
                                    className="opacity-0 group-hover:opacity-100 absolute top-2 right-2 text-xs border border-gray-200 rounded p-1"
                                    value={item.status}
                                    onChange={(e) => handleStatusChange(item.id, e.target.value)}
                                >
                                    <option value="Planned">Planned</option>
                                    <option value="In Progress">In Progress</option>
                                    <option value="Completed">Completed</option>
                                </select>
                            </div>

                            <h4 className="font-bold text-gray-800 text-sm mb-1">{item.title}</h4>
                            <p className="text-xs text-slate-500 mb-3 line-clamp-2">{item.reason}</p>

                            <div className="flex items-center gap-2 text-[10px] font-bold text-green-600 bg-green-50 px-2 py-1 rounded w-fit">
                                <Sparkles size={10} />
                                {item.impact}
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        );
    };

    return (
        <div className="h-[calc(100vh-100px)] flex flex-col space-y-6 pb-4 animate-in fade-in duration-500">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <div>
                    <h1 className="text-3xl font-black text-gray-900 flex items-center gap-2">
                        Product Roadmap <Map className="text-orange-500" />
                    </h1>
                    <p className="text-gray-500">AI-prioritized features based on user feedback.</p>
                </div>
                <button
                    onClick={handleGenerate}
                    disabled={generating}
                    className="px-5 py-3 bg-gradient-to-r from-orange-500 to-red-500 text-white rounded-xl shadow-lg shadow-orange-200 hover:shadow-orange-300 hover:scale-105 active:scale-95 transition-all font-bold flex items-center gap-2 disabled:opacity-70 disabled:cursor-not-allowed"
                >
                    {generating ? <Loader2 size={18} className="animate-spin" /> : <Sparkles size={18} />}
                    {generating ? 'Designing Strategy...' : 'Generate New Roadmap'}
                </button>
            </div>

            {/* Kanban Board */}
            {loading ? (
                <div className="flex-1 flex items-center justify-center">
                    <Loader2 size={40} className="animate-spin text-orange-500" />
                </div>
            ) : (
                <div className="flex-1 flex flex-col md:flex-row gap-6 overflow-x-auto pb-4">
                    <PriorityColumn title="High Priority" priority="High" icon={AlertCircle} color="bg-red-50" />
                    <PriorityColumn title="Medium Priority" priority="Medium" icon={Clock} color="bg-orange-50" />
                    <PriorityColumn title="Low Priority" priority="Low" icon={CheckCircle2} color="bg-blue-50" />
                </div>
            )}
        </div>
    );
};

export default AdminRoadmap;

